package com.bank.comp;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class CompensationDemo {
    private static final Logger log = Logger.getLogger("Compensation");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee(1L, "Rajesh", new BigDecimal("95000")),
            new Employee(2L, "Priya", new BigDecimal("250000")),
            new Employee(3L, "Amit", new BigDecimal("120000")),
            new Employee(4L, "Sneha", new BigDecimal("180000"))
        );
        CompensationService service = new CompensationService();
        Employee top = service.highestPaid(staff)
            .orElseThrow(() -> new IllegalStateException("no employees"));
        log.info(() -> "Top earner = " + top.getName() + " at Rs. " + top.getSalary());
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final Long id;
    private final String name;
    private final BigDecimal salary;
    Employee(Long id, String name, BigDecimal salary) { this.id = id; this.name = name; this.salary = salary; }
    String getName() { return name; }
    BigDecimal getSalary() { return salary; }
}

// ─── Would be in service/CompensationService.java ───
class CompensationService {
    // Single-arg reduce: keep the higher-salary employee of each pair → Optional max.
    Optional<Employee> highestPaid(List<Employee> employees) {
        return employees.stream()
            .reduce((a, b) -> a.getSalary().compareTo(b.getSalary()) >= 0 ? a : b);
    }
}
